<template>
  <div class="page">
    <div class="page-head">
      <div><span>购药协作</span><h1>{{ isAdmin?'代购订单与收货安全':'我的订单与收货核验' }}</h1><p>{{ isAdmin?'跟进物流，及时处理数量或药品信息不一致。':'查看物流，收到药后请拍照并逐项核对。' }}</p></div>
      <el-select v-if="isAdmin" v-model="careUserId" clearable placeholder="全部安心用药成员" size="large" @change="load"><el-option v-for="item in careUsers" :key="item.userId" :label="item.realName+'（'+item.username+'）'" :value="item.userId"/></el-select>
    </div>

    <div class="safety-tip"><el-icon><CircleCheckFilled /></el-icon><div><b>收货不是只点一下“确认”</b><span>系统会核对实收盒数、国药准字号和包装状态；全部一致后才计入药品库存。</span></div></div>

    <div class="order-grid">
      <el-card v-for="order in orders" :key="order.orderId" class="order-card" shadow="hover">
        <div class="order-top"><div><el-tag :type="receiptType(order.receiptStatus)">{{ receiptText(order.receiptStatus) }}</el-tag><b>{{ order.purchasePlatform }}</b></div><time>{{ order.orderTime }}</time></div>
        <div class="order-number">家庭订单 <b>#{{ order.orderId }}</b></div>
        <div class="metrics"><div><small>实付金额</small><strong>¥{{ money(order.actualTotal) }}</strong></div><div><small>预计到货</small><b>{{ order.expectedArrivalTime||'家属稍后补充' }}</b></div><div><small>快递公司</small><b>{{ order.carrierName||'待补充' }}</b></div><div><small>物流单号</small><b>{{ order.trackingNo||'待补充' }}</b></div></div>
        <div class="card-foot"><span><el-icon><Van /></el-icon>{{ logisticsText(order.logisticsStatus) }}</span><el-button type="primary" plain @click="openDetail(order)">查看详情</el-button></div>
      </el-card>
      <el-empty v-if="!orders.length" description="暂无代购订单" />
    </div>

    <el-dialog v-model="detailVisible" title="订单、物流与收货核验" width="820px" destroy-on-close>
      <template v-if="detail.order">
        <div class="detail-summary"><div><span>{{ detail.order.purchasePlatform }} · {{ detail.order.purchaseChannel==='ONLINE'?'线上购买':'线下购买' }}</span><h2>实付 ¥{{ money(detail.order.actualTotal) }}</h2><small>订单 #{{ detail.order.orderId }} · {{ detail.order.orderTime }}</small><small class="arrival">预计到货：{{ detail.order.expectedArrivalTime||'家属稍后补充' }}</small></div><ProtectedImage v-if="detail.order.screenshotUrl" :src="detail.order.screenshotUrl" fit="cover" class="order-proof"/></div>

        <section class="medicine-section"><div class="section-title"><h3>本次购买药品</h3><span>收货时按下列信息核对</span></div><div class="medicine-item" v-for="item in detail.items" :key="item.prescriptionId"><div class="medicine-name"><b>{{ item.medicineName }}</b><small>{{ item.brandName||'通用药品' }} · {{ item.specification }}</small><code>{{ item.approvalNumber||'请以药品档案中的准字号为准' }}</code></div><div><small>购买数量</small><strong>{{ item.quantityBoxes }} 盒</strong></div><div><small>有效期</small><strong>{{ item.expiryDate }}</strong></div></div></section>

        <section class="evidence-section">
          <div class="section-title"><div><h3>购药凭证时间线</h3><span>问诊、下单、付款和发票按发生时间长期留存</span></div><el-button v-if="isAdmin" type="primary" plain @click="openEvidence">补充凭证</el-button></div>
          <div v-if="detail.evidenceTimeline?.length" class="evidence-list">
            <article v-for="item in detail.evidenceTimeline" :key="item.evidenceId" class="evidence-card">
              <ProtectedImage :src="item.fileUrl" fit="cover" class="evidence-image" />
              <div><div class="evidence-head"><el-tag effect="plain">{{ item.evidenceTypeText }}</el-tag><time>{{ item.occurredTime }}</time></div><h4>{{ item.title }}</h4><p>{{ item.purchasePlatform||detail.order.purchasePlatform }}<b v-if="item.amount!==null&&item.amount!==undefined"> · ¥{{ money(item.amount) }}</b></p><small v-if="item.note">{{ item.note }}</small></div>
            </article>
          </div>
          <el-empty v-else description="暂未归档购药凭证" :image-size="72" />
        </section>

        <el-alert v-if="detail.order.receiptStatus==='EXCEPTION'" title="收货核验发现不一致，药品尚未计入库存" description="请家庭守护人查看下方核验记录，联系商家补发或更换。处理完成后重新开启核验。" type="error" :closable="false" show-icon class="receipt-alert" />
        <el-alert v-else-if="detail.order.receiptStatus==='VERIFIED'" title="收货核验已通过，药品已安全计入库存" type="success" :closable="false" show-icon class="receipt-alert" />

        <section v-if="detail.receiptVerifications?.length" class="verification-history"><div class="section-title"><h3>收货核验记录</h3><span>照片与每项比对结果会留存</span></div><div v-for="record in detail.receiptVerifications" :key="record.verificationId" class="verification-record"><div class="verification-head"><el-tag :type="record.checkResult==='VERIFIED'?'success':'danger'">{{ record.checkResult==='VERIFIED'?'全部一致':'发现异常' }}</el-tag><time>{{ record.createTime }}</time></div><ProtectedImage :src="record.photoUrl" fit="cover" class="receipt-photo"/><div class="check-list"><div v-for="check in parseChecks(record.checkJson)" :key="check.prescriptionId" :class="{mismatch:!check.matched}"><b>{{ check.medicineName }}</b><span>数量：应收 {{ check.expectedQuantityBoxes }} 盒 / 实收 {{ check.receivedQuantityBoxes }} 盒</span><span>准字号：{{ check.receivedApprovalNumber }}</span><span>包装：{{ check.packageIntact?'完好':'有破损' }}</span><span>规格剂量：{{ check.specificationConfirmed?'一致':'不一致' }}</span></div></div><p v-if="record.note">说明：{{ record.note }}</p></div></section>

        <section class="tracking-section"><div class="section-title"><h3>物流进度</h3><a v-if="detail.trackingQueryUrl" :href="detail.trackingQueryUrl" target="_blank">去快递平台核对</a></div><el-timeline><el-timeline-item v-for="event in detail.events" :key="event.eventId" :timestamp="event.occurredTime" :type="event.statusCode==='DELIVERED'?'success':event.statusCode==='RECEIPT_EXCEPTION'?'danger':'primary'"><b>{{ event.statusText }}</b><p>{{ event.detail }}</p></el-timeline-item></el-timeline></section>

        <el-form v-if="isAdmin" label-position="top" class="admin-tools"><div class="form-grid"><el-form-item label="快递公司"><el-input v-model="logistics.carrierName" placeholder="京东物流/中通/申通等"/></el-form-item><el-form-item label="快递代码"><el-input v-model="logistics.carrierCode" placeholder="jd/zhongtong等"/></el-form-item><el-form-item label="物流单号"><el-input v-model="logistics.trackingNo"/></el-form-item></div><div class="form-grid two"><el-form-item label="新增物流状态"><el-select v-model="logistics.statusCode" @change="logistics.statusText=logisticsText($event)"><el-option v-for="status in logisticsStatuses" :key="status.code" :label="status.text" :value="status.code"/></el-select></el-form-item><el-form-item label="具体说明"><el-input v-model="logistics.detail" placeholder="例如：快件已到达武汉转运中心"/></el-form-item></div><div class="tool-actions"><el-button type="primary" :loading="savingLogistics" @click="saveLogistics">保存物流并提醒安心用药端</el-button><el-button v-if="detail.order.receiptStatus==='EXCEPTION'" type="danger" plain @click="reopenReceipt">异常已处理，重新开启核验</el-button></div></el-form>

        <div v-else-if="detail.order.receiptStatus==='PENDING'" class="receipt-entry"><div><el-icon><CameraFilled /></el-icon><span><b>药品已经拿到手了吗？</b><small>请准备好收到的全部药品，拍一张清晰合照，再逐项核对。</small></span></div><el-button type="success" size="large" @click="startReceiptCheck">开始收货核验</el-button></div>
      </template>
    </el-dialog>

    <el-dialog v-model="evidenceVisible" title="补充购药凭证" width="620px" destroy-on-close>
      <el-alert title="图片会绑定当前订单并按家庭权限保护" description="请不要上传与本次购药无关的身份证、银行卡等资料。" type="info" :closable="false" show-icon />
      <el-form label-position="top" class="evidence-form">
        <div class="form-grid two"><el-form-item label="凭证类型"><el-select v-model="evidenceForm.evidenceType" @change="evidenceForm.title=evidenceTypeText($event)"><el-option v-for="item in evidenceTypes" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="evidenceForm.occurredTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="选择凭证对应时间"/></el-form-item></div>
        <div class="form-grid two"><el-form-item label="标题"><el-input v-model.trim="evidenceForm.title" maxlength="120"/></el-form-item><el-form-item label="金额（可不填）"><el-input-number v-model="evidenceForm.amount" :min="0" :precision="2" :step="10" controls-position="right"/></el-form-item></div>
        <el-form-item label="购药平台"><el-input v-model.trim="evidenceForm.purchasePlatform" maxlength="100" placeholder="如京东健康、医院门诊、线下药店"/></el-form-item>
        <el-form-item label="凭证图片"><el-upload :show-file-list="false" :http-request="uploadEvidenceImage" accept="image/jpeg,image/png,image/webp"><ProtectedImage v-if="evidenceForm.fileUrl" :src="evidenceForm.fileUrl" fit="cover" :preview="false" class="evidence-upload-preview"/><div v-else class="evidence-upload-placeholder"><el-icon><CameraFilled /></el-icon><b>{{ uploadingEvidence?'正在上传…':'选择清晰截图或照片' }}</b><span>单张不超过 5MB</span></div></el-upload></el-form-item>
        <el-form-item label="说明（可不填）"><el-input v-model.trim="evidenceForm.note" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item>
      </el-form>
      <template #footer><el-button @click="evidenceVisible=false">取消</el-button><el-button type="primary" :loading="savingEvidence" @click="saveEvidence">归档到时间线</el-button></template>
    </el-dialog>

    <el-dialog v-model="receiptVisible" title="收货安全核验" width="760px" destroy-on-close>
      <el-steps :active="1" finish-status="success" simple class="receipt-steps"><el-step title="收到药品"/><el-step title="逐项核对"/><el-step title="安全入库"/></el-steps>
      <el-alert title="请看实物填写，不要凭记忆输入" description="如果数量、国药准字号或包装有任何一项不一致，系统会通知家庭守护人处理，不会把这批药计入库存。" type="warning" :closable="false" show-icon />
      <div class="photo-upload"><el-upload :show-file-list="false" :http-request="uploadReceiptPhoto" accept="image/jpeg,image/png,image/webp"><ProtectedImage v-if="receiptForm.photoUrl" :src="receiptForm.photoUrl" fit="cover" :preview="false"/><div v-else class="upload-placeholder"><el-icon><CameraFilled /></el-icon><b>{{ uploadingReceipt?'正在上传…':'拍照或上传全部药品合照' }}</b><span>图片需清楚看到药品包装</span></div></el-upload></div>
      <div class="receipt-items"><div v-for="item in receiptForm.items" :key="item.prescriptionId" class="receipt-item"><div class="receipt-item-head"><span><b>{{ item.medicineName }}</b><small>{{ item.specification }}</small></span><el-tag>应收 {{ item.expectedQuantity }} 盒</el-tag></div><div class="receipt-form-grid"><label><span>实际收到多少盒</span><el-input-number v-model="item.receivedQuantityBoxes" :min="0" :max="999"/></label><label><span>包装上的国药准字号</span><el-input v-model.trim="item.approvalNumber" maxlength="80" placeholder="例如：国药准字H12345678"/></label><label class="package-check"><span>外包装是否完整无破损</span><el-radio-group v-model="item.packageIntact"><el-radio-button :value="true">完好</el-radio-button><el-radio-button :value="false">有破损</el-radio-button></el-radio-group></label><label class="package-check"><span>规格、剂量是否与订单一致</span><el-radio-group v-model="item.specificationConfirmed"><el-radio-button :value="true">一致</el-radio-button><el-radio-button :value="false">不一致</el-radio-button></el-radio-group></label></div><p>订单记录准字号：<code>{{ item.expectedApprovalNumber||'药品档案未显示，请仔细看实物' }}</code></p></div></div>
      <el-form-item label="需要告诉家属的情况（选填）"><el-input v-model="receiptForm.note" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="例如：外包装压扁、少了两盒、药名看起来不一样等"/></el-form-item>
      <template #footer><el-button @click="receiptVisible=false">稍后核验</el-button><el-button type="primary" size="large" :loading="submittingReceipt" @click="submitReceiptCheck">提交核验结果</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useUserStore } from '../stores/user'
import { addPurchaseEvidence, getFamilyOrderDetail, getFamilyOrders, reopenFamilyOrderReceipt, updateOrderLogistics, verifyFamilyOrderReceipt } from '../api/family'
import { getUserList } from '../api/user'
import request from '../utils/request'
import ProtectedImage from '../components/ProtectedImage.vue'

const store=useUserStore(),isAdmin=['ADMIN','GUARDIAN'].includes(store.userInfo.role),orders=ref([]),careUsers=ref([]),careUserId=ref(isAdmin?null:store.userInfo.userId),detailVisible=ref(false),receiptVisible=ref(false),evidenceVisible=ref(false),uploadingReceipt=ref(false),submittingReceipt=ref(false),uploadingEvidence=ref(false),savingEvidence=ref(false),savingLogistics=ref(false)
const detail=reactive({order:null,items:[],events:[],receiptVerifications:[],evidenceTimeline:[],trackingQueryUrl:null})
const logisticsStatuses=[{code:'ORDERED',text:'已下单'},{code:'PICKED_UP',text:'快递已揽收'},{code:'IN_TRANSIT',text:'运输中'},{code:'OUT_FOR_DELIVERY',text:'正在派送'},{code:'DELIVERED',text:'快递显示已送达'},{code:'EXCEPTION',text:'物流异常'}]
const logistics=reactive({statusCode:'IN_TRANSIT',statusText:'运输中',detail:'',occurredTime:'',carrierCode:'',carrierName:'',trackingNo:''})
const receiptForm=reactive({photoUrl:'',note:'',items:[]})
const evidenceTypes=[{value:'CONSULTATION',label:'问诊记录'},{value:'ORDER_SCREENSHOT',label:'下单截图'},{value:'PAYMENT',label:'付款凭证'},{value:'INVOICE',label:'发票凭证'}]
const evidenceForm=reactive({evidenceType:'PAYMENT',fileId:null,fileUrl:'',title:'付款凭证',occurredTime:'',amount:null,purchasePlatform:'',note:''})
const money=value=>Number(value||0).toFixed(2)
const logisticsText=code=>logisticsStatuses.find(item=>item.code===code)?.text||({RECEIPT_EXCEPTION:'收货核验异常',RECEIPT_REOPENED:'等待重新核验'}[code]||code)
const receiptText=status=>({PENDING:'等待收货核验',VERIFIED:'收货核验通过',EXCEPTION:'收货发现异常'}[status]||'等待收货核验')
const receiptType=status=>status==='VERIFIED'?'success':status==='EXCEPTION'?'danger':'warning'
const nowText=()=>{const date=new Date(),pad=n=>String(n).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`}
const parseChecks=json=>{try{return JSON.parse(json||'[]')}catch{return[]}}
const evidenceTypeText=value=>evidenceTypes.find(item=>item.value===value)?.label||'购药凭证'
const load=async()=>{const res=await getFamilyOrders(careUserId.value);orders.value=res.data||[]}
const openDetail=async order=>{const res=await getFamilyOrderDetail(order.orderId);Object.assign(detail,res.data);Object.assign(logistics,{statusCode:detail.order.logisticsStatus||'IN_TRANSIT',statusText:logisticsText(detail.order.logisticsStatus),detail:'',occurredTime:nowText(),carrierCode:detail.order.carrierCode||'',carrierName:detail.order.carrierName||'',trackingNo:detail.order.trackingNo||''});detailVisible.value=true}
const saveLogistics=async()=>{if(!logistics.carrierName?.trim()||!logistics.trackingNo?.trim())return ElMessage.warning('请先填写快递公司和物流单号');savingLogistics.value=true;try{await updateOrderLogistics(detail.order.orderId,{...logistics,occurredTime:nowText()});ElMessage.success('物流信息已保存并发送提醒');await openDetail(detail.order);await load()}finally{savingLogistics.value=false}}
const openEvidence=()=>{Object.assign(evidenceForm,{evidenceType:'PAYMENT',fileId:null,fileUrl:'',title:'付款凭证',occurredTime:detail.order.orderTime||nowText(),amount:Number(detail.order.actualTotal||0),purchasePlatform:detail.order.purchasePlatform||'',note:''});evidenceVisible.value=true}
const uploadEvidenceImage=async option=>{uploadingEvidence.value=true;try{const formData=new FormData();formData.append('file',option.file);formData.append('category',evidenceForm.evidenceType);const res=await request.post('/files/images',formData);evidenceForm.fileId=res.data.fileId;evidenceForm.fileUrl=res.data.url;ElMessage.success('凭证图片已安全上传')}finally{uploadingEvidence.value=false}}
const saveEvidence=async()=>{if(!evidenceForm.fileId)return ElMessage.warning('请先上传凭证图片');if(!evidenceForm.title||!evidenceForm.occurredTime)return ElMessage.warning('请填写凭证标题和发生时间');savingEvidence.value=true;try{await addPurchaseEvidence(detail.order.orderId,{evidenceType:evidenceForm.evidenceType,fileId:evidenceForm.fileId,title:evidenceForm.title,occurredTime:evidenceForm.occurredTime,amount:evidenceForm.amount,purchasePlatform:evidenceForm.purchasePlatform,note:evidenceForm.note});evidenceVisible.value=false;ElMessage.success('凭证已归档并提醒家庭成员');await openDetail(detail.order)}finally{savingEvidence.value=false}}
const startReceiptCheck=()=>{Object.assign(receiptForm,{photoUrl:'',note:'',items:detail.items.map(item=>({prescriptionId:item.prescriptionId,medicineName:item.medicineName,specification:item.specification,expectedQuantity:Number(item.quantityBoxes),expectedApprovalNumber:item.approvalNumber||'',receivedQuantityBoxes:Number(item.quantityBoxes),approvalNumber:'',packageIntact:null,specificationConfirmed:null}))});receiptVisible.value=true}
const uploadReceiptPhoto=async option=>{uploadingReceipt.value=true;try{const formData=new FormData();formData.append('file',option.file);formData.append('category','RECEIPT_PHOTO');const res=await request.post('/files/images',formData);receiptForm.photoUrl=res.data.url;ElMessage.success('收货照片已安全上传')}finally{uploadingReceipt.value=false}}
const submitReceiptCheck=async()=>{if(!receiptForm.photoUrl)return ElMessage.warning('请先拍照或上传全部药品合照');if(receiptForm.items.some(item=>item.receivedQuantityBoxes===null||!item.approvalNumber||item.packageIntact===null||item.specificationConfirmed===null))return ElMessage.warning('请把每种药品的数量、国药准字号、包装和规格剂量填写完整');await ElMessageBox.confirm('确认以上内容是对照收到的药品实物填写的吗？提交后系统会自动判断是否一致。','提交收货核验',{type:'warning',confirmButtonText:'确认提交',cancelButtonText:'再检查一下'});submittingReceipt.value=true;try{const res=await verifyFamilyOrderReceipt(detail.order.orderId,{photoUrl:receiptForm.photoUrl,note:receiptForm.note,items:receiptForm.items.map(item=>({prescriptionId:item.prescriptionId,receivedQuantityBoxes:item.receivedQuantityBoxes,approvalNumber:item.approvalNumber,packageIntact:item.packageIntact,specificationConfirmed:item.specificationConfirmed}))});receiptVisible.value=false;const passed=res.data.checkResult==='VERIFIED';passed?ElMessage.success('全部核对一致，药品已安全计入库存'):ElMessage.error('发现信息不一致，已通知家庭守护人处理');await openDetail(detail.order);load()}finally{submittingReceipt.value=false}}
const reopenReceipt=async()=>{await ElMessageBox.confirm('请确认已联系商家完成补发或换货。重新开启后，安心用药端可再次拍照核验。','重新开启核验',{type:'warning'});await reopenFamilyOrderReceipt(detail.order.orderId);ElMessage.success('已重新开启收货核验');await openDetail(detail.order);load()}
onMounted(async()=>{if(isAdmin){const res=await getUserList('ELDER');careUsers.value=res.data||[]}load()})
</script>

